package com.transportlogistics.app.fuel.infrastructure.adapters.out.persistence;

import com.transportlogistics.app.fuel.application.ports.in.FuelCardImportUseCase;
import com.transportlogistics.app.fuel.application.ports.out.FuelCardImportParser;
import com.transportlogistics.app.fuel.application.ports.out.FuelCardTransactionRepository;
import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Sort;
import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Component;
import java.time.OffsetDateTime; import java.util.*;

@Component
class FuelCardTransactionPersistenceAdapter implements FuelCardTransactionRepository {
 private final FuelCardImportBatchJpaRepository batches; private final FuelCardTransactionJpaRepository transactions;
 private final FuelCardIndicatorJpaRepository indicators; private final FuelCardReconciliationJpaRepository history;
 FuelCardTransactionPersistenceAdapter(FuelCardImportBatchJpaRepository b,FuelCardTransactionJpaRepository t,FuelCardIndicatorJpaRepository i,FuelCardReconciliationJpaRepository h){batches=b;transactions=t;indicators=i;history=h;}
 @Override public Optional<FuelCardImportUseCase.Batch> findBatch(UUID t,UUID p,String id){return batches.findByTenantIdAndProviderIdAndProviderBatchId(t,p,id).map(this::map);}
 @Override public Optional<FuelCardImportUseCase.Batch> findBatchByHash(UUID t,UUID p,String h){return batches.findByTenantIdAndProviderIdAndFileHash(t,p,h).map(this::map);}
 @Override public FuelCardImportUseCase.Batch saveBatch(FuelCardImportUseCase.Batch b,UUID t){var e=new FuelCardImportBatchJpaEntity();e.setId(b.id());e.setTenantId(t);e.setProviderId(b.providerId());e.setProviderBatchId(b.providerBatchId());e.setFileHash(b.fileHash());e.setGeneratedAt(b.generatedAt());e.setTransactionCount(b.transactionCount());e.setImportedCount(b.importedCount());e.setReviewCount(b.reviewCount());e.setImportedBy(b.importedBy());e.setCreatedAt(b.createdAt());return map(batches.save(e));}
 @Override public List<FuelCardImportUseCase.Batch> batches(UUID t,int p,int l){return batches.findByTenantIdOrderByCreatedAtDesc(t,PageRequest.of(p,l)).stream().map(this::map).toList();}
 @Override public Optional<FuelCardImportUseCase.Batch> batch(UUID t,UUID id){return batches.findByTenantIdAndId(t,id).map(this::map);}
 @Override public Optional<FuelCardImportUseCase.Transaction> findProviderTransaction(UUID t,UUID p,String id){return transactions.findByTenantIdAndProviderIdAndProviderTransactionId(t,p,id).map(this::map);}
 @Override public boolean providerTransactionHashMatches(UUID t,UUID p,String id,String hash){return transactions.findByTenantIdAndProviderIdAndProviderTransactionId(t,p,id).map(e->e.getCanonicalHash().equals(hash)).orElse(false);}
 @Override public void markReversed(UUID t,UUID p,String id){var e=transactions.findByTenantIdAndProviderIdAndProviderTransactionId(t,p,id).orElseThrow(()->new IllegalArgumentException("FUEL_CARD_IMPORT_INVALID"));e.setLocalStatus(e.getReconciledPurchaseId()==null?"REVERSED":"REVIEW_REQUIRED");transactions.save(e);}
 @Override public FuelCardImportUseCase.Transaction saveTransaction(FuelCardImportParser.ParsedTransaction f,UUID t,UUID batch,UUID provider,UUID card,UUID actor,String status,Set<String> codes,OffsetDateTime now){var e=new FuelCardTransactionJpaEntity();e.setId(UUID.randomUUID());e.setTenantId(t);e.setBatchId(batch);e.setProviderId(provider);e.setCardId(card);e.setProviderTransactionId(f.providerTransactionId());e.setCanonicalHash(f.canonicalHash());e.setTransactionKind(f.transactionKind());e.setOriginalProviderTransactionId(f.originalProviderTransactionId());e.setTransactionTimestamp(f.transactionTimestamp());e.setPostedTimestamp(f.postedTimestamp());e.setStationReference(f.stationReference());e.setFuelType(f.fuelType());e.setQuantityLitres(f.quantityLitres());e.setUnitPrice(f.unitPrice());e.setTotalAmount(f.totalAmount());e.setCurrency(f.currency());e.setProviderVehicleReference(f.providerVehicleReference());e.setProviderDriverReference(f.providerDriverReference());e.setTripId(f.tripId());e.setProviderStatus(f.providerStatus());e.setLocalStatus(status);e.setImportedBy(actor);e.setCreatedAt(now);e=transactions.save(e);for(String code:codes){var i=new FuelCardIndicatorJpaEntity();i.setId(UUID.randomUUID());i.setTenantId(t);i.setTransactionId(e.getId());i.setCode(code);i.setCreatedAt(now);indicators.save(i);}return map(e);}
 @Override public List<FuelCardImportUseCase.Transaction> transactions(UUID t,FuelCardImportUseCase.TransactionSearch s){
  Specification<FuelCardTransactionJpaEntity> specification=(root,query,builder)->{
   var predicates=new ArrayList<jakarta.persistence.criteria.Predicate>();predicates.add(builder.equal(root.get("tenantId"),t));
   if(s.cardId()!=null)predicates.add(builder.equal(root.get("cardId"),s.cardId()));if(s.providerId()!=null)predicates.add(builder.equal(root.get("providerId"),s.providerId()));
   if(s.from()!=null)predicates.add(builder.greaterThanOrEqualTo(root.get("transactionTimestamp"),s.from()));if(s.to()!=null)predicates.add(builder.lessThanOrEqualTo(root.get("transactionTimestamp"),s.to()));
   if(s.localStatus()!=null)predicates.add(builder.equal(root.get("localStatus"),s.localStatus().toUpperCase(Locale.ROOT)));
   if(s.reconciliationStatus()!=null){boolean reconciled="RECONCILED".equalsIgnoreCase(s.reconciliationStatus());predicates.add(reconciled?builder.isNotNull(root.get("reconciledPurchaseId")):builder.isNull(root.get("reconciledPurchaseId")));}
   if(s.reviewRequired()!=null)predicates.add(builder.equal(root.get("localStatus"),s.reviewRequired()?"REVIEW_REQUIRED":"IMPORTED"));
   if(s.indicator()!=null){var indicator=query.subquery(UUID.class);var indicatorRoot=indicator.from(FuelCardIndicatorJpaEntity.class);indicator.select(indicatorRoot.get("id")).where(builder.equal(indicatorRoot.get("tenantId"),t),builder.equal(indicatorRoot.get("transactionId"),root.get("id")),builder.equal(indicatorRoot.get("code"),s.indicator().toUpperCase(Locale.ROOT)));predicates.add(builder.exists(indicator));}
   return builder.and(predicates.toArray(jakarta.persistence.criteria.Predicate[]::new));};
  var direction="asc".equalsIgnoreCase(s.direction())?Sort.Direction.ASC:Sort.Direction.DESC;var field=switch(s.sort()==null?"transactionTimestamp":s.sort()){case "postedTimestamp"->"postedTimestamp";case "amount"->"totalAmount";case "status"->"localStatus";case "createdAt"->"createdAt";default->"transactionTimestamp";};
  var pageable=PageRequest.of(s.page(),s.limit(),Sort.by(direction,field).and(Sort.by(Sort.Direction.ASC,"id")));
  return transactions.findAll(specification,pageable).stream().map(this::map).toList();}
 @Override public Optional<FuelCardImportUseCase.Transaction> transaction(UUID t,UUID id){return transactions.findByTenantIdAndId(t,id).map(this::map);}
 @Override public Totals totals(UUID t,UUID card,OffsetDateTime from,OffsetDateTime to){Object[] row=transactions.totals(t,card,from,to);if(row.length==1&&row[0] instanceof Object[] nested)row=nested;return new Totals((java.math.BigDecimal)row[0],(java.math.BigDecimal)row[1]);}
 @Override public FuelCardImportUseCase.Transaction reconcile(UUID t,UUID id,UUID actor,FuelCardImportUseCase.Action a,OffsetDateTime now){var e=transactions.findByTenantIdAndId(t,id).orElseThrow(()->new IllegalArgumentException("FUEL_CARD_TRANSACTION_NOT_FOUND"));String action=a.action().toUpperCase(Locale.ROOT);switch(action){case "MATCH"->{if(!"PURCHASE".equals(e.getTransactionKind()))throw new IllegalArgumentException("FUEL_CARD_RECONCILIATION_INVALID");e.setReconciledPurchaseId(a.purchaseId());e.setLocalStatus("RECONCILED");}case "UNMATCH"->{e.setReconciledPurchaseId(null);e.setLocalStatus("REVIEW_REQUIRED");}case "REJECT"->{e.setReconciledPurchaseId(null);e.setLocalStatus("REJECTED");}default->throw new IllegalArgumentException("FUEL_CARD_RECONCILIATION_INVALID");}e=transactions.save(e);var h=new FuelCardReconciliationJpaEntity();h.setId(UUID.randomUUID());h.setTenantId(t);h.setTransactionId(id);h.setAction(action);h.setPurchaseId(a.purchaseId());h.setReason(a.reason());h.setActorId(actor);h.setCreatedAt(now);history.save(h);return map(e);}
 private FuelCardImportUseCase.Batch map(FuelCardImportBatchJpaEntity e){return new FuelCardImportUseCase.Batch(e.getId(),e.getProviderId(),e.getProviderBatchId(),e.getFileHash(),e.getGeneratedAt(),e.getTransactionCount(),e.getImportedCount(),e.getReviewCount(),e.getImportedBy(),e.getCreatedAt());}
 private FuelCardImportUseCase.Transaction map(FuelCardTransactionJpaEntity e){Set<String> codes=new LinkedHashSet<>();indicators.findByTenantIdAndTransactionId(e.getTenantId(),e.getId()).forEach(i->codes.add(i.getCode()));return new FuelCardImportUseCase.Transaction(e.getId(),e.getBatchId(),e.getProviderId(),e.getCardId(),e.getProviderTransactionId(),e.getTransactionKind(),e.getOriginalProviderTransactionId(),e.getTransactionTimestamp(),e.getPostedTimestamp(),e.getStationReference(),e.getFuelType(),e.getQuantityLitres(),e.getUnitPrice(),e.getTotalAmount(),e.getCurrency(),e.getTripId(),e.getProviderStatus(),e.getLocalStatus(),e.getReconciledPurchaseId(),Set.copyOf(codes),e.getImportedBy(),e.getVersion(),e.getCreatedAt());}
}
